async function runSeed() {
  try {
    console.log('[Mongo Seeder] Connecting to MongoDB Atlas...');
    await mongoose.connect(MONGODB_URI);
    console.log('[Mongo Seeder] Connected to MongoDB Atlas successfully.');

    const db = mongoose.connection.db;

    console.log('[Mongo Seeder] Clearing existing categories and products...');
    try { await db.collection('products').dropIndex('variants.sku_1'); } catch (e) {}
    await db.collection('categories').deleteMany({});
    await db.collection('products').deleteMany({});

    console.log('[Mongo Seeder] Inserting ' + categoriesData.length + ' official categories...');
    const catDocs = categoriesData.map(c => ({
      ...c,
      createdAt: new Date(),
      updatedAt: new Date()
    }));
    await db.collection('categories').insertMany(catDocs);

    console.log('[Mongo Seeder] Inserting ' + productsData.length + ' official products...');
    const prodDocs = productsData.map(p => ({
      ...p,
      _id: new mongoose.Types.ObjectId(),
      specifications: new Map(Object.entries(p.specifications)),
      createdAt: new Date(),
      updatedAt: new Date()
    }));
    await db.collection('products').insertMany(prodDocs);

    const totalCats = await db.collection('categories').countDocuments();
    const totalProds = await db.collection('products').countDocuments();

    console.log('SUCCESS: Seeded ' + totalCats + ' categories and ' + totalProds + ' products into MongoDB Atlas!');
    process.exit(0);
  } catch (err) {
    console.error('[Mongo Seeder ERROR]:', err);
    process.exit(1);
  }
}

runSeed();
